    input [7:0] A, 
    input [7:0] B, 
    output reg [15:0] Z, 
    output reg [7:0] SSEG_CA, 
    output reg [3:0] SSEG_AN, 
    input btnU, 
    input btnL,
    input btnR,
    input btnD
    );always @ (*) 
begin 
    if (btnU == 1)
        Z = A * B;
    else if (btnL == 1)
        Z = A / B;
    else if (btnR == 1)
        Z = A + B;
    else if (btnD == 1)
        Z = A - B;
    else
        Z = 0;
end 

always @ (*) begin
    SSEG_AN[0] = 0; 
    case (Z[3:0]) 
    0 : SSEG_CA = 8'b01000000; 
    1 : SSEG_CA = 8'b01111001;
