description:
Design a synchronous register with an asynchronous active-low reset. This register holds a WIDTH-bit value and updates its output Q to the input D when the enable signal en is asserted, triggered on the rising edge of the clock signal clkrst_core_clk. If the reset signal clkrst_core_rst_n is deasserted, the output Q is reset to a predefined value RESET_VAL.
module top_module(

   Q,

   D, en, clkrst_core_clk, clkrst_core_rst_n
   );

code:
module top_module(

   Q,

   D, en, clkrst_core_clk, clkrst_core_rst_n
   );parameter WIDTH = 8;
  parameter RESET_VAL = 8'd0;
  input [WIDTH-1:0] D;
  output reg [WIDTH-1:0] Q;
  input en;
  input clkrst_core_clk, clkrst_core_rst_n;

  always @(posedge clkrst_core_clk, negedge clkrst_core_rst_n) begin
    if(~clkrst_core_rst_n) begin
      Q <= RESET_VAL;
    end
    else if(en) begin
      Q <= D;
    end
  end
endmodule

