            @(negedge clk);
            data_in = 8'hCC;
            load = 1;
            shift = 1;
            serial_in = 1;
            @(posedge clk);

            #1;
            load = 0;
            shift = 0;
            #1;

            check_outputs(8'hCC);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("\nTestcase %0d: Hold State Verification", test_num);
            reset_dut();


            @(negedge clk);
            data_in = 8'h55;
            load = 1;
            @(posedge clk);


            #1 load = 0;
            shift = 0;


            repeat(2) @(posedge clk);

            #1 #1;
 check_outputs(8'h55);
        end
        endtask

    task testcase006;

        integer i;
        reg [7:0] pattern;
        begin
            test_num = test_num + 1;
            $display("\nTestcase %0d: Full 8-bit Serial Fill", test_num);
            reset_dut();

            pattern = 8'b1010_1010;
            @(negedge clk);
